// Inserts clearly-flagged DEMONSTRATION responses (is_demo = 1) so the dashboard can be
// previewed before real data exists. Demo rows are excluded from analytics and exports
// unless "Include demo data" is switched on, and can be removed with `npm run db:purge-demo`.
//
// The numbers are generated by a toy model — they are NOT findings and must never be
// reported as results.

import "dotenv/config";
import { randomUUID } from "node:crypto";
import { generateCode } from "../../shared/participantCode.js";
import type { Answers, Stage } from "../../shared/types.js";
import { createSession, getSession, insertResponse, openDatabase, type DB } from "../db.js";
import { validateAndScore } from "../scoring.js";
import { KNOWLEDGE_MAX, questionsForStage } from "../survey/definition.js";

/** Small deterministic PRNG (mulberry32) so repeated seeds give the same demo data. */
function rng(seed: number) {
  return () => {
    seed |= 0;
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function simulateAnswers(stage: Stage, ability: number, rand: () => number): Answers {
  const answers: Answers = {};
  const pick = <T,>(xs: T[]) => xs[Math.floor(rand() * xs.length)];
  for (const q of questionsForStage(stage)) {
    if (q.section === "about") {
      if (rand() < 0.9) answers[q.id] = pick(q.options!).id;
      continue;
    }
    if (q.key) {
      const correct = q.key.correct;
      const wrong = q.options!.filter((o) => !correct.includes(o.id) && o.id !== "unsure").map((o) => o.id);
      const r = rand();
      if (q.kind === "multi") {
        answers[q.id] = r < ability ? [...correct] : [...correct.slice(0, 2), pick(wrong)];
      } else {
        answers[q.id] = r < ability ? correct[0] : r < ability + 0.08 ? "unsure" : pick(wrong);
      }
      continue;
    }
    if (q.id === "s_confidence") answers[q.id] = Math.min(5, Math.max(1, Math.round(2 + ability * 3 + (rand() - 0.5) * 2)));
    if (q.id === "s_estimate") answers[q.id] = Math.min(10, Math.max(0, Math.round(ability * 10 + (rand() - 0.3) * 4)));
    if (q.id === "r_exposure") answers[q.id] = rand() < 0.75 ? ["social_posts", ...(rand() < 0.5 ? ["videos"] : [])] : ["none"];
  }
  return answers;
}

function insertDemo(db: DB, stage: Stage, code: string, answers: Answers, startedAt: Date, minutes: number) {
  const id = randomUUID();
  createSession(db, { id, stage, participantCode: code, startedAt: startedAt.toISOString(), isDemo: true });
  const session = getSession(db, id)!;
  const submittedAt = new Date(startedAt.getTime() + minutes * 60_000).toISOString();
  insertResponse(db, { id: randomUUID(), session, scored: validateAndScore(stage, answers), knowledgeMax: KNOWLEDGE_MAX, submittedAt });
}

const path = process.env.DATABASE_PATH?.trim() || "./data/hlac.db";
const db = openDatabase(path);
const rand = rng(20261028);
const bytes = (n: number) => Uint8Array.from({ length: n }, () => Math.floor(rand() * 256));
const PRE_N = 36;
const day = 24 * 60 * 60 * 1000;
const base = Date.now() - 14 * day;

db.transaction(() => {
  for (let i = 0; i < PRE_N; i++) {
    const code = generateCode(bytes);
    const ability = 0.35 + rand() * 0.35;
    insertDemo(db, "pre", code, simulateAnswers("pre", ability, rand), new Date(base + rand() * 3 * day), 4 + rand() * 6);
    if (rand() < 0.8) {
      const post = Math.min(0.95, ability + (rand() - 0.25) * 0.4);
      insertDemo(db, "post", code, simulateAnswers("post", post, rand), new Date(base + 9 * day + rand() * 3 * day), 3 + rand() * 5);
    }
  }
  // A few abandoned sessions and unmatched POST responses, as in real collection.
  for (let i = 0; i < 4; i++) createSession(db, { id: randomUUID(), stage: "pre", participantCode: generateCode(bytes), isDemo: true });
  for (let i = 0; i < 3; i++) insertDemo(db, "post", generateCode(bytes), simulateAnswers("post", 0.6, rand), new Date(base + 10 * day), 5);
})();

const n = db.prepare("SELECT COUNT(*) AS n FROM responses WHERE is_demo = 1").get() as { n: number };
console.log(`Inserted demonstration data. Demo responses now in database: ${n.n}.`);
console.log("These are NOT real participants. Remove them with: npm run db:purge-demo");
db.close();
